INSERT INTO dtc_codes (code, manufacturer, description_ko, summary_ko, tts_phrase) VALUES
('P0469', 'GENERIC', '증발 가스 퍼지 유량 센서 회로의 간헐적 문제가 발생했습니다.', '증발가스 퍼지 센서 이상', '증발 가스 퍼지 유량 센서 회로에 간헐적인 문제를 감지했습니다.'),
