-- DTC Code Definitions Table (Korean Optimized)
CREATE TABLE IF NOT EXISTS dtc_codes (
    code VARCHAR(20) NOT NULL,
    manufacturer VARCHAR(50) DEFAULT 'GENERIC',
    description_ko TEXT,
    summary_ko VARCHAR(255),
    tts_phrase TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (code, manufacturer)
);

ON CONFLICT (code, manufacturer) DO UPDATE SET
    description_ko = EXCLUDED.description_ko,
    summary_ko = EXCLUDED.summary_ko,
    tts_phrase = EXCLUDED.tts_phrase;

